{
  "predictors": [
    {
      "name": "Digital Engagement Index",
      "construction": "Constructed by measuring the frequency of updates in digital communications (e.g., press releases, website updates) over the past year.",
      "rationale": "Firms more engaged with digital communication may be more in tune with market trends and consumer needs.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Intellectual Property Growth Rate",
      "construction": "Calculated as the year-over-year percentage change in the number of patents granted to a firm, using data from the U.S. Patent Office.",
      "rationale": "Rapid growth in intellectual property may indicate innovation and future competitive advantage.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Board Diversity Score",
      "construction": "Scored based on the percentage of board members from diverse backgrounds, using annual proxy statements.",
      "rationale": "Diverse boards may provide a wider range of perspectives and improve strategic decision-making.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Customer Satisfaction Index",
      "construction": "Average customer satisfaction score derived from consumer surveys and industry reports over the past year.",
      "rationale": "Firms with higher customer satisfaction may experience better customer retention and sales growth.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Environmental Innovation Ratio",
      "construction": "Ratio of environmental patents to total patents granted in the past year, using data from the U.S. Patent Office.",
      "rationale": "Firms focused on environmental innovation may be better positioned for regulatory changes and environmental trends.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Employee Retention Rate",
      "construction": "Percentage of employees retained over the past year, derived from annual reports and company disclosures.",
      "rationale": "High employee retention can signal strong corporate culture and operational stability.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Social Media Sentiment Index",
      "construction": "Aggregate sentiment score of social media mentions over the past quarter, using sentiment analysis tools.",
      "rationale": "Positive social media sentiment can indicate favorable consumer perception and brand strength.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Supply Chain Efficiency Ratio",
      "construction": "Ratio of sales to inventory turnover over the past year, using financial statement data.",
      "rationale": "Efficient supply chains can reduce costs and enhance profitability.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Product Launch Frequency",
      "construction": "Number of new product launches over the past two years, derived from press releases and industry reports.",
      "rationale": "Frequent product launches may suggest innovation and adaptability to market demands.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Research Collaboration Index",
      "construction": "Number of joint research projects or partnerships with academic institutions in the past year, from press releases and company reports.",
      "rationale": "Collaboration with academic institutions may lead to cutting-edge research and technology advances.",
      "higher_returns_for": "High values of the measure"
    }
  ]
}
